SourceCode.Declaration:
/// <summary>
/// One purchase order line, carrying everything the handheld needs to drive its remaining steps.
///
/// The dimension flags matter as much as the quantities. Over OData the app had to fetch the
/// released product separately just to learn whether the item needs a batch or a serial, which
/// cost a whole round trip at the item step. They are read here from InventDimGroupSetup, which
/// is cached in the AOS, so they are effectively free once the line is in hand.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPurchLineContract
{
    LineNum             lineNumber;
    ItemId              itemId;
    Name                itemName;
    UnitOfMeasureSymbol purchUnit;
    UnitOfMeasureSymbol inventUnit;

    PurchQty            orderedQty;
    PurchQty            receivedQty;
    PurchQty            remainingQty;
    PurchQty            uncommittedQty;

    InventSiteId        siteId;
    InventLocationId    warehouseId;
    WMSLocationId       locationId;

    boolean             batchRequired;
    boolean             serialRequired;
    boolean             locationRequired;

    Percent             overDeliveryPct;
    Percent             underDeliveryPct;

    str                 lineStatus;
    boolean             stopped;

    // Populated only when the receiving process is in LineClaim mode; see
    // HSMobileOpsProcessSetup and HSMobileOpsLineClaim. Blank when the line is free, or when
    // the process is not in that mode at all - the client tells the two apart by ConcurrencyMode
    // on the order response, not by guessing from these being empty.
    str                 claimedByUserName;
    str                 claimedByDisplayName;
    utcdatetime         claimExpiresUtc;

    str     configId;
    str     sizeId;
    str     colorId;
    str     styleId;
}

Method.Source:
[DataMemberAttribute('LineNumber')]
public LineNum parmLineNumber(LineNum _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('ItemId')]
public ItemId parmItemId(ItemId _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('ItemName')]
public Name parmItemName(Name _value = itemName)
{
    itemName = _value;
    return itemName;
}

[DataMemberAttribute('PurchUnit')]
public UnitOfMeasureSymbol parmPurchUnit(UnitOfMeasureSymbol _value = purchUnit)
{
    purchUnit = _value;
    return purchUnit;
}

[DataMemberAttribute('InventUnit')]
public UnitOfMeasureSymbol parmInventUnit(UnitOfMeasureSymbol _value = inventUnit)
{
    inventUnit = _value;
    return inventUnit;
}

[DataMemberAttribute('OrderedQty')]
public PurchQty parmOrderedQty(PurchQty _value = orderedQty)
{
    orderedQty = _value;
    return orderedQty;
}

/// <summary>
/// Already received physically, in the purchase unit.
///
/// Derived on the server as ordered minus remaining, both of which are columns on PurchLine.
/// Over OData this number did not exist at all and had to be summed from ProductReceiptLines,
/// which was an extra query per order and got the answer wrong if the paging was not followed.
/// </summary>
[DataMemberAttribute('ReceivedQty')]
public PurchQty parmReceivedQty(PurchQty _value = receivedQty)
{
    receivedQty = _value;
    return receivedQty;
}

[DataMemberAttribute('RemainingQty')]
public PurchQty parmRemainingQty(PurchQty _value = remainingQty)
{
    remainingQty = _value;
    return remainingQty;
}

/// <summary>
/// Already staged on a device (a HSMobileOpsPostQueue row landed, not yet processed), in the
/// purchase unit. Netted out of RemainingQty on this same line so two offline sessions on the
/// same order cannot jointly over-receive; see HSMobileOpsReceivingService::stagedQtyByLine.
/// </summary>
[DataMemberAttribute('UncommittedQty')]
public PurchQty parmUncommittedQty(PurchQty _value = uncommittedQty)
{
    uncommittedQty = _value;
    return uncommittedQty;
}

[DataMemberAttribute('SiteId')]
public InventSiteId parmSiteId(InventSiteId _value = siteId)
{
    siteId = _value;
    return siteId;
}

[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public WMSLocationId parmLocationId(WMSLocationId _value = locationId)
{
    locationId = _value;
    return locationId;
}

/// <summary>
/// True when the item's tracking dimension group has batch numbers active.
///
/// The handheld shows a batch prompt if and only if this is set. Getting it wrong is not a
/// cosmetic problem in either direction: prompting for a dimension the item does not track
/// produces a posting the AOS rejects, and skipping one it does track produces the same.
/// </summary>
[DataMemberAttribute('BatchRequired')]
public boolean parmBatchRequired(boolean _value = batchRequired)
{
    batchRequired = _value;
    return batchRequired;
}

[DataMemberAttribute('SerialRequired')]
public boolean parmSerialRequired(boolean _value = serialRequired)
{
    serialRequired = _value;
    return serialRequired;
}

[DataMemberAttribute('LocationRequired')]
public boolean parmLocationRequired(boolean _value = locationRequired)
{
    locationRequired = _value;
    return locationRequired;
}

[DataMemberAttribute('OverDeliveryPct')]
public Percent parmOverDeliveryPct(Percent _value = overDeliveryPct)
