    return overDeliveryPct;
}

[DataMemberAttribute('UnderDeliveryPct')]
public Percent parmUnderDeliveryPct(Percent _value = underDeliveryPct)
{
    underDeliveryPct = _value;
    return underDeliveryPct;
}

[DataMemberAttribute('LineStatus')]
public str parmLineStatus(str _value = lineStatus)
{
    lineStatus = _value;
    return lineStatus;
}

[DataMemberAttribute('Stopped')]
public boolean parmStopped(boolean _value = stopped)
{
    stopped = _value;
    return stopped;
}

[DataMemberAttribute('ClaimedByUserName')]
public str parmClaimedByUserName(str _value = claimedByUserName)
{
    claimedByUserName = _value;
    return claimedByUserName;
}

[DataMemberAttribute('ClaimedByDisplayName')]
